import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Documents Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Documents Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/documents-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Documents Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/documents-overview"}]]},"headers":[],"relativePath":"user-guide/documents-overview.md","filePath":"user-guide/documents-overview.md","lastUpdated":1788612600000}'),d={name:"user-guide/documents-overview.md"};function s(i,e,n,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="documents-module" tabindex="-1">Documents Module <a class="header-anchor" href="#documents-module" aria-label="Permalink to &quot;Documents Module&quot;">​</a></h1><p>Operations module on the frozen platform. A workspace <strong>flat file library</strong> — upload shared files, organize them with flat categories, optionally link them to CRM/HR/project records, and download them — built on the free <strong>Storage</strong> quota. Documents is a <strong>free Marketplace opt-in</strong> with a <strong>hard dependency on Storage</strong>.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/documents">documents.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/documents">documents.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/documents">documents.md</a> · <a href="/deployment/documents-production-readiness">production readiness</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/assets-overview">assets-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-documents">../api/tenant-v1-documents.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Upload workspace files (title, optional description, optional category, file blob)</li><li>Flat categories (name/slug/sort/active) — no nested folders</li><li><strong>Soft links</strong> to entitled Leads, Contacts, Companies, Projects, Employees, Assets, and Tasks (optional; module + permission gated per record type)</li><li>Download original file by authenticated API</li><li>Soft delete / restore; permanent delete removes the object from disk</li><li>Bulk soft delete (active list) and bulk permanent delete (Deleted only)</li><li>Table view with search, category filter, and trash filters</li><li>KPIs via <code>GET /documents/stats</code> (total, categorized, uncategorized)</li><li>File bytes count toward the workspace <strong>Storage</strong> quota (<code>documents.size_bytes</code>)</li><li>Module licensing (<code>module:documents</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, <strong>requires Storage</strong></li><li>Audit logging on create / update / soft delete / restore / force delete</li><li>Soft-deleted files purged with workspace trash retention (<code>trash:purge-expired</code>)</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>documents.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code></p><p><strong>Delete / force delete ownership:</strong> users may only soft-delete or permanently delete documents they uploaded (<code>created_by</code>), even when they hold <code>documents.delete</code> / <code>documents.force.delete</code>. The workspace owner (<code>superadmin</code> role) may delete any document. View / create / update / restore are unchanged permission gates.</p><p>Default roles: <strong>admin</strong> = all except <code>force.delete</code>; <strong>manager</strong> = view / create / update; <strong>staff</strong> = view.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><p>Enable Documents from Marketplace (free). Catalog: slug <code>documents</code>, category <code>operations</code> (Operations), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 85</code>, version <strong>1.4.0</strong>.</p><p><strong>Hard dependency:</strong> Storage (<code>storage</code>) must be entitled first. Install fails without it.</p><p>To make Documents billable later, use Central → <strong>Modules</strong> → Documents and set <code>is_billable</code> plus prices via the existing <strong>Update Module</strong> API — no new Central UI.</p><h2 id="storage-quota" tabindex="-1">Storage quota <a class="header-anchor" href="#storage-quota" aria-label="Permalink to &quot;Storage quota&quot;">​</a></h2><p>Uploaded document bytes are included in <code>WorkspaceStorageService::usedBytes()</code>. Soft-deleted documents drop out of the sum until restored; force-delete removes the file from object storage.</p><p>See <a href="/user-guide/storage">Storage</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Nested folders / directory trees</li><li>Versioning / check-in / check-out</li><li>Preview / in-browser viewers</li><li>Dashboard widget</li><li>Automation triggers</li></ul>',19)])])}const g=t(d,[["render",s]]);export{p as __pageData,g as default};
